import request from "supertest";
import jwt from "jsonwebtoken";
import app from "../../src/app.js";
import {
  closeDatabase,
  createUser,
  syncDatabase,
  truncateDatabase,
} from "../setup/testDatabase.js";
import { JWT_SECRET } from "../../src/config/auth.js";
import { Room } from "../../src/models/index.js";
import { NUMBER } from "sequelize";

function authHeader(user) {
  return `Bearer ${jwt.sign({ id: user.id, role: user.role }, JWT_SECRET)}`;
}

describe("Room routes", () => {
  beforeAll(async () => {
    await syncDatabase();
  });

  beforeEach(async () => {
    await truncateDatabase();
  });

  afterAll(async () => {
    await closeDatabase();
  });

  test("creates a new room for authenticated user", async () => {
    const user = await createUser();

    const response = await request(app)
      .post("/api/room/create")
      .set("Authorization", authHeader(user))
      .send({
        password: "12345678",
      });

    expect(response.status).toBe(201);
    expect(response.body.code).toBeEqual(expect.any(NUMBER));
  });

  test("enters an existing room with correct password for authenticated user", async () => {
    const user = await createUser();
    const room = await Room.create({ password: "12345678" });

    const response = await request(app)
      .post("/api/room/enter")
      .set("Authorization", authHeader(user))
      .send({
        code: room.code,
      });

    expect(response.status).toBe(200);
    expect(response.body.message).toBe("Room was found successfully");
  });
});
